CREATE TABLE IF NOT EXISTS  dm_otc_n.trd_deri_stru_type_mth( 
	 deri_type string COMMENT '衍生品类型' , otc_deri_type string COMMENT '合约类型' , add_nom_prin_mth string COMMENT '本月新增名义本金规模（亿元）' , add_nom_prin_pmth string COMMENT '上月新增名义本金规模（亿元）' , add_nom_prin_mom string COMMENT '新增名义本金环比' , add_nom_prin_mom_flag string COMMENT '新增名义本金环比升降标志' , mom_abs_rank_no string COMMENT '环比绝对值排序' , add_nom_prin_year_rate string COMMENT '今年新增名义本金占比' , dura_nom_prin_mth_rate string COMMENT '本月存续名义本金占比' , rate_diff_abs_gt_pct5_flag string COMMENT '占比差绝对值是否大于百分之五' , rate_diff_abs_gt_pct2_flag string COMMENT '占比差绝对值是否大于百分之二' ) COMMENT '月度衍生品结构类型交易情况' PARTITIONED BY ( busi_mon string COMMENT '月份' ) STORED AS ORC